with c as (
  insert into public.courses(title, description, category, hours, pass_score, published, audience, created_by)
  values ('การใช้และการจัดเก็บสารเคมีอย่างปลอดภัย',
    'เรียนรู้การอ่านฉลากและเอกสาร SDS การใช้สารเคมีอย่างปลอดภัย การจัดเก็บสารเคมีที่เข้ากันไม่ได้ และการจัดการเมื่อสารเคมีหกรั่วไหล',
    'ความปลอดภัย', 2, 80, true, 'restricted',
    (select user_id from public.user_roles where role='admin' limit 1))
  returning id
), l as (
  insert into public.lessons(course_id, position, title, kind, body)
  select id, 1, 'ฉลากสารเคมีและเอกสาร SDS', 'text', E'ก่อนใช้สารเคมีทุกครั้งต้องอ่านฉลากและเอกสารข้อมูลความปลอดภัย (SDS)\n\n• สัญลักษณ์ GHS บอกอันตราย เช่น ไวไฟ กัดกร่อน เป็นพิษ ระคายเคือง\n• SDS มี 16 หัวข้อ เช่น อันตราย การปฐมพยาบาล การจัดเก็บ การกำจัด\n• ภาชนะที่แบ่งบรรจุต้องติดฉลากชื่อสาร ความเข้มข้น วันที่ และผู้รับผิดชอบเสมอ' from c
  union all select id, 2, 'การใช้สารเคมีอย่างปลอดภัย', 'text', E'• สวมอุปกรณ์ป้องกัน (PPE) ตามที่ SDS กำหนด: ถุงมือ แว่นตา หน้ากาก เสื้อกาวน์\n• ใช้ในที่อากาศถ่ายเทหรือในตู้ดูดควัน\n• ห้ามผสมสารเคมีเอง เช่น น้ำยาฟอกขาว (คลอรีน) กับแอมโมเนียหรือกรด จะเกิดก๊าซพิษ\n• เจือจางกรด: เทกรดลงน้ำ ห้ามเทน้ำลงกรด\n• ห้ามรับประทานอาหารหรือดื่มน้ำในพื้นที่ใช้สารเคมี' from c
  union all select id, 3, 'การจัดเก็บสารเคมีและสารที่เข้ากันไม่ได้', 'text', E'• แยกเก็บตามประเภทอันตราย: ไวไฟ / กรด / ด่าง / ออกซิไดซ์ / เป็นพิษ\n• สารไวไฟเก็บในตู้นิรภัย ห่างจากความร้อนและประกายไฟ\n• กรดแยกจากด่าง สารออกซิไดซ์แยกจากสารไวไฟ\n• วางสารเคมีของเหลวไว้ชั้นล่าง ไม่สูงกว่าระดับสายตา มีถาดรองกันหก\n• ใช้หลักเข้าก่อนออกก่อน (FIFO) และตรวจวันหมดอายุทุกเดือน' from c
  union all select id, 4, 'การจัดการเมื่อสารเคมีหกรั่วไหลและการปฐมพยาบาล', 'text', E'เมื่อสารเคมีหก:\n1. แจ้งเตือนคนรอบข้าง กั้นพื้นที่\n2. สวม PPE ให้เหมาะสม\n3. ใช้ชุดจัดการสารเคมีหก (Spill kit) ซับจากขอบเข้าหาตรงกลาง\n4. ทิ้งวัสดุปนเปื้อนเป็นขยะอันตราย และรายงานหัวหน้า\n\nปฐมพยาบาล: สัมผัสผิวหนังหรือเข้าตา ให้ล้างด้วยน้ำสะอาดไหลผ่านอย่างน้อย 15 นาที แล้วพบแพทย์ พร้อมนำ SDS ไปด้วย' from c
  returning course_id
), q as (
  insert into public.questions(course_id, position, question, options, correct_index)
  select id, 1, 'เอกสารใดให้ข้อมูลอันตรายและวิธีจัดการสารเคมีครบถ้วนที่สุด', '["ใบเสร็จการสั่งซื้อ","SDS (Safety Data Sheet)","คู่มือการใช้เครื่องมือ","ใบเบิกพัสดุ"]'::jsonb, 1 from c
  union all select id, 2, 'การเจือจางกรดที่ถูกต้องคือข้อใด', '["เทน้ำลงในกรด","เทกรดลงในน้ำช้าๆ","เทพร้อมกันในภาชนะ","ต้มน้ำก่อนแล้วเทกรด"]'::jsonb, 1 from c
  union all select id, 3, 'สารใดห้ามผสมกับน้ำยาฟอกขาว (คลอรีน) เพราะทำให้เกิดก๊าซพิษ', '["น้ำสะอาด","แอมโมเนีย","สบู่ก้อน","น้ำเกลือ"]'::jsonb, 1 from c
  union all select id, 4, 'การจัดเก็บสารเคมีข้อใดถูกต้อง', '["เก็บกรดและด่างไว้ด้วยกัน","วางของเหลวไว้ชั้นบนสุด","แยกสารออกซิไดซ์ออกจากสารไวไฟ","เก็บสารไวไฟใกล้เครื่องทำความร้อน"]'::jsonb, 2 from c
  union all select id, 5, 'สารเคมีกระเด็นเข้าตา ควรล้างด้วยน้ำสะอาดอย่างน้อยกี่นาที', '["1 นาที","5 นาที","15 นาที","ไม่ต้องล้าง ให้รีบพบแพทย์"]'::jsonb, 2 from c
  returning course_id
)
insert into public.course_access(course_id, kind, value)
select id, 'division', 'ฝ่ายการพยาบาล' from c
union all select id, 'department', 'หน่วยเทคนิคเครื่องมือแพทย์' from c;